#include <stdio.h>
#include <string.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char digits[1005];
    for (int i = 0; i < N; i++) {
        int d;
        scanf("%d", &d);
        digits[i] = (char)('0' + d);
    }

    for (int startLen = 1; startLen <= N; startLen++) {
        if (digits[0] == '0') continue;

        char current[1005];
        memcpy(current, digits, startLen);
        int currentLen = startLen;
        int pos = 0;
        int valid = 1;

        while (pos < N) {
            if (pos + currentLen > N ||
                memcmp(digits + pos, current, currentLen) != 0) {
                valid = 0;
                break;
            }

            pos += currentLen;
            if (pos == N) break;

            int i = currentLen - 1;
            while (i >= 0 && current[i] == '9') {
                current[i] = '0';
                i--;
            }

            if (i < 0) {
                memmove(current + 1, current, currentLen);
                current[0] = '1';
                currentLen++;
            } else {
                current[i]++;
            }
        }

        if (valid && pos == N) {
            fwrite(digits, 1, startLen, stdout);
            putchar('\n');
            return 0;
        }
    }

    return 0;
}
