#include <stdio.h>
#include <string.h>

static void increment(char *number, int *length) {
    int i = *length - 1;

    while (i >= 0 && number[i] == '9') {
        number[i] = '0';
        i--;
    }

    if (i >= 0) {
        number[i]++;
    } else {
        memmove(number + 1, number, (size_t)*length);
        number[0] = '1';
        (*length)++;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char digits[1005];
    for (int i = 0, d; i < n; i++) {
        scanf("%d", &d);
        digits[i] = (char)('0' + d);
    }

    for (int first_len = 1; first_len <= n; first_len++) {
        if (digits[0] == '0') break;

        char current[2005];
        memcpy(current, digits, (size_t)first_len);
        int current_len = first_len;
        int pos = 0;
        int valid = 1;

        while (pos < n) {
            if (pos + current_len > n ||
                memcmp(digits + pos, current, (size_t)current_len) != 0) {
                valid = 0;
                break;
            }

            pos += current_len;
            if (pos < n) increment(current, &current_len);
        }

        if (valid) {
            printf("%.*s\n", first_len, digits);
            return 0;
        }
    }

    return 0;
}
